/**
 * The web reminder offer: when a browser tab may offer "Want a nudge
 * tomorrow?", and what pressing a button saves (marketer's decision F3,
 * `marketing/research/2026-10-18-day2-retention.md`, 18 Oct 2026).
 *
 * The phone apps have their own offer (`session/FirstReminder.tsx`), which
 * schedules a local reminder; a browser cannot, so here the offer turns on
 * what the server can send: a note in this browser (Web Push) or an e-mail,
 * both only when the learner has been away. Every rule below has a test.
 */
import { dayIndex } from '@lexpad/core';
import { db, getMeta, setMeta, type MetaShape } from '@/db/schema.js';
import { loadSettings } from '@/db/repo.js';
import { localTimeZone } from '@/lib/format.js';
import { isDesktopShell, isNativeShell } from '@/lib/platform/detect.js';
import { FIRST_PRACTICE_DAYS, reminderHour } from '@/features/session/reminderOffer.js';

export type WebReminderNote = MetaShape['webReminder'];

/**
 * The hours an e-mail reminder may name. The server's day-2 note is sent
 * between 09:00 and 20:00 (F1), so an e-mail reminder set at 23:00 would
 * promise a time it never keeps. Not data: it is the rule the spec states
 * for this offer, the same on every account.
 */
export const EMAIL_EARLIEST_HOUR = 9;
export const EMAIL_LATEST_HOUR = 20;

/** A browser tab: not the Android or iPhone shell, and not the desktop app's window. */
export function isWebTab(): boolean {
  return !isNativeShell() && !isDesktopShell();
}

/** The time a browser reminder names: the hour this session happened in. */
export function browserReminderTime(now: Date = new Date()): string {
  return reminderHour(now);
}

/** The time an e-mail reminder names: this session's hour, kept between 09:00 and 20:00. */
export function emailReminderTime(now: Date = new Date()): string {
  const hour = Math.min(EMAIL_LATEST_HOUR, Math.max(EMAIL_EARLIEST_HOUR, now.getHours()));
  return `${String(hour).padStart(2, '0')}:00`;
}

/** Today as the app counts days, in this device's zone. */
export function today(now: Date = new Date()): number {
  return dayIndex(now, localTimeZone());
}

/**
 * Whether this summary offers the reminder: only in a browser tab, only on
 * the first day with practice, only with no reminder time set, and only
 * once on this device ("Not now" included).
 */
export async function offersOnSummary(): Promise<boolean> {
  if (!isWebTab()) return false;
  const [note, settings] = await Promise.all([getMeta('webReminder'), loadSettings()]);
  if (note.offeredDay !== null || note.notNow) return false;
  if ((settings?.reminderTime ?? '') !== '') return false;
  const days = await db.dayStats.filter((stat) => stat.reviewed > 0).count();
  return days <= FIRST_PRACTICE_DAYS;
}

/**
 * Whether Today shows its one later line: the summary offered it on an
 * earlier day, the learner came back, still has no reminder time and never
 * pressed "Not now". Shown on one day only, then never again.
 */
export async function offersOnToday(day: number = today()): Promise<boolean> {
  if (!isWebTab()) return false;
  const [note, settings] = await Promise.all([getMeta('webReminder'), loadSettings()]);
  return todayLineDue(note, settings?.reminderTime ?? '', day);
}

/** The Today rule on its own, for the tests. */
export function todayLineDue(note: WebReminderNote, reminderTime: string, day: number): boolean {
  if (note.notNow || reminderTime !== '') return false;
  if (note.offeredDay === null || day <= note.offeredDay) return false;
  return note.lineDay === null || note.lineDay === day;
}

async function update(patch: Partial<WebReminderNote>): Promise<void> {
  await db.transaction('rw', db.meta, async () => {
    const note = await getMeta('webReminder');
    await setMeta('webReminder', { ...note, ...patch });
  });
}

/** The summary showed the offer: asked, once on this device. */
export function markOffered(day: number = today()): Promise<void> {
  return update({ offeredDay: day });
}

/** Today showed its later line: this day only. */
export function markLineShown(day: number = today()): Promise<void> {
  return update({ lineDay: day });
}

/** "Not now": never offered again here; Settings keeps the switch. */
export function markNotNow(): Promise<void> {
  return update({ notNow: true });
}
